import{_ as t,a as s,o as r,a6 as a}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse(`{"title":"Delete Customer Address","description":"","frontmatter":{"outline":false,"examples":[{"id":"delete-customer-address","title":"Delete Customer Address","description":"Remove an address from the customer's address book.","request":"DELETE /api/shop/customer-addresses/1\\nX-STOREFRONT-KEY: pk_storefront_PvlE42nWGsKRVIf8bDlJngTPAdWAZbIy\\nAuthorization: Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...\\n","response":"HTTP/1.1 204 No Content\\n","commonErrors":[{"error":"401 Unauthorized","cause":"Customer not authenticated","solution":"Provide valid Bearer token"},{"error":"404 Not Found","cause":"No such address, or the address belongs to another customer — both answer the same way","solution":"Delete only IDs returned by Get Customer Addresses for this customer"}]}]},"headers":[],"relativePath":"api/rest-api/shop/customers/delete-customer-address.md","filePath":"api/rest-api/shop/customers/delete-customer-address.md","lastUpdated":1786429091000}`),o={name:"api/rest-api/shop/customers/delete-customer-address.md"};function d(i,e,n,l,h,c){return r(),s("div",null,e[0]||(e[0]=[a('<h1 id="delete-customer-address" tabindex="-1">Delete Customer Address <a class="header-anchor" href="#delete-customer-address" aria-label="Permalink to &quot;Delete Customer Address&quot;">​</a></h1><p>Remove an address from the customer&#39;s address book.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DELETE /api/shop/customer-addresses/{addressId}</span></span></code></pre></div><h2 id="url-parameters" tabindex="-1">URL Parameters <a class="header-anchor" href="#url-parameters" aria-label="Permalink to &quot;URL Parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>addressId</code></td><td>integer</td><td>Yes</td><td>Address ID to delete</td></tr></tbody></table><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key</td></tr><tr><td><code>Authorization</code></td><td>Yes</td><td>Bearer token (customer login required)</td></tr></tbody></table><h2 id="response" tabindex="-1">Response <a class="header-anchor" href="#response" aria-label="Permalink to &quot;Response&quot;">​</a></h2><p><code>204 No Content</code> with an empty body. There is no confirmation payload — the status is the confirmation.</p><h2 id="deletion-behaviour" tabindex="-1">Deletion Behaviour <a class="header-anchor" href="#deletion-behaviour" aria-label="Permalink to &quot;Deletion Behaviour&quot;">​</a></h2><ul><li>The address row is removed outright and cannot be recovered.</li><li>Deleting the default address does <strong>not</strong> promote another one. The customer is left with no default until one is set explicitly, so re-set it with <a href="/api/rest-api/shop/customers/update-customer-address.html">Update Address</a> if the flow depends on a default.</li><li>The last remaining address can be deleted; an empty address book is allowed.</li><li>Addresses already captured on an order are snapshots stored with that order, so past orders keep their address after this call.</li><li>An ID belonging to another customer answers <code>404</code>, the same as an ID that does not exist — the endpoint never confirms that someone else&#39;s address is real.</li></ul><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li><strong>Address-book &quot;remove&quot; button</strong> — call with the row&#39;s <code>id</code>, then re-render from <a href="/api/rest-api/shop/customers/get-customer-addresses.html">Get Customer Addresses</a>; the response body carries nothing to render from.</li><li><strong>Cleaning up after a checkout</strong> — the addresses saved during checkout carry an <code>addressType</code> of <code>cart_billing</code> or <code>cart_shipping</code>, so they can be pruned separately from the shopper&#39;s own entries.</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ul><li><strong>Re-fetch the list after deleting</strong> — a <code>204</code> returns no data, so the client cannot patch its state from the response.</li><li><strong>Check whether the deleted row was the default</strong> — nothing is promoted in its place, and a checkout that assumes a default will find none.</li><li><strong>Treat <code>404</code> as &quot;not yours or not there&quot;</strong> — do not branch on it as proof the address never existed.</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/customers/get-customer-addresses.html">Get Customer Addresses</a> — the customer&#39;s saved address book</li><li><a href="/api/rest-api/shop/customers/create-customer-address.html">Create Customer Address</a> — add an address to the book</li><li><a href="/api/rest-api/shop/customers/update-customer-address.html">Update Customer Address</a> — patch one saved address</li></ul>',18)]))}const m=t(o,[["render",d]]);export{p as __pageData,m as default};
